import time
from typing import Callable

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = capacity

    def allow(self, cost: float = 1) -> bool:
        elapsed_time = time.time() - self.clock()
        tokens_refilled = int(elapsed_time // self.refill_per_sec)
        if tokens_refilled < cost:
            self.tokens -= tokens_refilled
            return True
        else:
            self.tokens -= cost
            return False

    @property
    def tokens(self) -> float:
        return self.capacity - self.tokens

def clock():
    return time.time()
